def glom(target, spec, **kwargs):
    scope = kwargs.pop('scope', _DEFAULT_SCOPE)
    default = kwargs.pop('default', _MISSING)
    skip_exc = kwargs.pop('skip_exc', () if default is _MISSING else GlomError)
    glom_debug = kwargs.pop('glom_debug', GLOM_DEBUG)
    if kwargs:
        raise TypeError(f'unexpected keyword arguments: {list(kwargs.keys())!r}')

    if not isinstance(scope, ChainMap):
        scope = ChainMap(dict(scope))

    scope = scope.new_child({
        Path: [],
        T: target,
        Spec: spec,
        UP: scope,
        LAST_CHILD_SCOPE: scope,
        CHILD_ERRORS: [],
        MODE: AUTO,
        MIN_MODE: AUTO,
        NO_PYFRAME: True,
    })

    try:
        ret = scope[glom](target, spec, scope)
    except skip_exc as e:
        if default is _MISSING:
            if glom_debug:
                raise
            if isinstance(e, GlomError):
                e._finalize(scope)
                raise
            raise
        return default
    except GlomError as e:
        if glom_debug:
            raise
        e._finalize(scope)
        raise
    except Exception as e:
        if isinstance(skip_exc, tuple) and isinstance(e, skip_exc):
            if default is _MISSING:
                raise
            return default
        raise
    return ret
